# owner: platform
import unittest

from hourglass.rounding import round_label
from hourglass.rounding import round_labels, round_span
from hourglass.parsing import parse_span
from hourglass.models import Span

class RoundSpanTests(unittest.TestCase):
    def test_snaps_both_ends(self):
        span = parse_span("09:07-17:08")
        self.assertEqual(
            round_span(span, 15), parse_span("09:00-17:15")
        )

    def test_below_half_rounds_down(self):
        span = parse_span("09:07-10:22")
        self.assertEqual(
            round_span(span, 15), parse_span("09:00-10:15")
        )

    def test_half_step_rounds_up(self):
        span = parse_span("09:08-10:23")
        self.assertEqual(
            round_span(span, 15), parse_span("09:15-10:30")
        )

    def test_end_of_day_stays_in_range(self):
        result = round_span(Span(1400, 1439), 30)
        self.assertEqual(result, Span(1410, 1440))

    def test_collapsed_span_raises(self):
        with self.assertRaises(ValueError):
            round_span(Span(540, 544), 15)

class LabelTests(unittest.TestCase):
    def test_label(self):
        span = parse_span("09:02-17:14")
        self.assertEqual(
            round_label(span, 15), "09:00-17:15 (8h 15m)"
        )

    def test_short_label(self):
        span = parse_span("09:00-09:30")
        self.assertEqual(
            round_label(span, 30), "09:00-09:30 (0h 30m)"
        )

    def test_labels_keep_order(self):
        spans = [Span(600, 660), Span(60, 120)]
        self.assertEqual(
            round_labels(spans, 60),
            ["10:00-11:00 (1h 0m)", "01:00-02:00 (1h 0m)"],
        )

    def test_empty_list(self):
        self.assertEqual(round_labels([], 15), [])

class BadStepTests(unittest.TestCase):
    def test_bad_steps_raise(self):
        spans = [Span(60, 600)]
        for step in (0, -15, 7, 45, 90, 2.5):
            with self.subTest(step=step):
                with self.assertRaises(ValueError):
                    round_labels(spans, step)

    def test_bad_step_raises_without_spans(self):
        with self.assertRaises(ValueError):
            round_labels([], 0)

    def test_good_steps_accepted(self):
        spans = [Span(60, 600)]
        for step in (1, 5, 6, 10, 15, 20, 30, 60):
            with self.subTest(step=step):
                result = round_labels(spans, step)
                self.assertEqual(len(result), 1)
